// Test double of `expo/config`, which the config loader of `@expo/agent-cli` requires from the
// project. `getConfig` answers with the file STUB_EXPO_CONFIG_JSON names, else by evaluating the
// project's `app.config.js` the way the real one does, else with the static file; it throws
// STUB_EXPO_CONFIG_ERROR when set, and records each call beside the stub bin's invocations.
'use strict';

const fs = require('node:fs');
const path = require('node:path');

const STATIC_FILES = ['app.config.json', 'app.json'];
const DYNAMIC_FILES = ['app.config.ts', 'app.config.js'];

exports.getConfig = function getConfig(projectRoot, options = {}) {
  const logPath =
    process.env.STUB_EXPO_LOG || path.join(process.cwd(), 'stub-expo-invocations.jsonl');
  const flags = Object.entries(options)
    .filter(([, value]) => value === true)
    .map(([key]) => `--${key}`);
  fs.appendFileSync(
    logPath,
    JSON.stringify({
      args: ['expo/config', 'getConfig', ...flags],
      cwd: process.cwd(),
      ci: process.env.CI ?? null,
      isTTY: Boolean(process.stdout.isTTY),
      nodeEnv: process.env.NODE_ENV ?? null,
    }) + '\n'
  );
  if (process.env.STUB_EXPO_CONFIG_ERROR) {
    throw new Error(process.env.STUB_EXPO_CONFIG_ERROR);
  }

  const staticConfigPath = firstExisting(projectRoot, STATIC_FILES);
  const dynamicConfigPath = firstExisting(projectRoot, DYNAMIC_FILES);
  const staticExp = staticConfigPath ? unwrap(JSON.parse(fs.readFileSync(staticConfigPath, 'utf8'))) : {};
  let exp;
  if (process.env.STUB_EXPO_CONFIG_JSON) {
    exp = JSON.parse(fs.readFileSync(process.env.STUB_EXPO_CONFIG_JSON, 'utf8'));
  } else if (dynamicConfigPath) {
    const mod = require(dynamicConfigPath);
    const exported = mod && mod.default != null ? mod.default : mod;
    exp = unwrap(typeof exported === 'function' ? exported({ config: staticExp }) : exported);
  } else {
    exp = staticExp;
  }
  const pkg = JSON.parse(fs.readFileSync(path.join(projectRoot, 'package.json'), 'utf8'));
  // The real `getConfig` fills `slug` from the package name when the config names none.
  if (!exp.slug && pkg.name) {
    exp = { ...exp, slug: pkg.name };
  }
  return { exp, pkg, rootConfig: {}, staticConfigPath, dynamicConfigPath, hasUnusedStaticConfig: false };
};

function firstExisting(projectRoot, names) {
  for (const name of names) {
    const file = path.join(projectRoot, name);
    if (fs.existsSync(file)) {
      return file;
    }
  }
  return null;
}

/** Both `{ "expo": { ... } }` and a bare config object are valid. */
function unwrap(config) {
  return config && typeof config === 'object' && config.expo ? config.expo : (config ?? {});
}
